node -e '
const Cart = require("./src/cart");
// Probe 1: can a 100% discount (or any valid discount) yield a negative or wrong-signed total?
let neg = 0, nonzero100 = 0, sample = null;
for (let n = 0; n < 200000; n++) {
  const c = new Cart();
  const lines = 1 + Math.floor(Math.random() * 4);
  for (let k = 0; k < lines; k++) c.addItem("i" + k, Math.round(Math.random() * 100000) / 100, 1 + Math.floor(Math.random() * 9));
  c.applyDiscount(100);
  const t100 = c.getTotal();
  if (t100 !== 0) { nonzero100++; sample = sample || t100; }
  const d = Math.round(Math.random() * 10000) / 100;
  c.applyDiscount(d);
  if (c.getTotal() < 0) neg++;
}
console.log("100% discount nonzero:", nonzero100, "sample:", sample, "| negative totals:", neg);
// Probe 2: caller-input side effects and rejected-call state
const c = new Cart(); c.addItem("a", 1, 1);
const before = JSON.stringify(c.items);
for (const f of [() => c.addItem("a", 1, -1), () => c.addItem("a", -1, 1), () => c.removeItem("zz"), () => c.applyDiscount(101)]) { try { f(); } catch {} }
console.log("state unchanged after rejected calls:", JSON.stringify(c.items) === before && c.discount === 0);
// Probe 3: odd inputs to error formatting
for (const v of [Symbol("s"), Object.create(null), { toString() { return "obj"; } }, 10n]) {
  try { c.addItem(v, 1, 1); } catch (e) { console.log(typeof v, "->", e.name + ":", e.message); }
}
try { c.applyDiscount(Object.create(null)); } catch (e) { console.log("discount null-proto ->", e.name + ":", e.message); }
// Probe 4: price mismatch on merge and huge quantities
const m = new Cart(); m.addItem("x", 1, 1); m.addItem("x", 2, 1); console.log("merge with new price total:", m.getTotal(), JSON.stringify(m.items));
const h = new Cart(); h.addItem("h", 1e308, 10); console.log("overflow total:", h.getTotal());
const q = new Cart(); q.addItem("q", 1, Number.MAX_SAFE_INTEGER); q.addItem("q", 1, 2); console.log("quantity past safe int:", q.items[0].quantity, Number.isSafeInteger(q.items[0].quantity));
'

